public class BrainTeaseTriviaGame extends Application {
    private Stage stage; private final Game game = new Game(); private Timeline timer; private Label timerLabel; private List<Q> lightningDeck; private List<Q> roundOne; private List<Q> roundTwo; private List<Q> jeopardyRound; private List<Q> millionaireRound; private List<Q> lightningRound;
    private final Preferences prefs = Preferences.userNodeForPackage(BrainTeaseTriviaGame.class);
    @Override public void start(Stage s) { stage=s; stage.setTitle("BrainTease Trivia Challenge"); stage.setResizable(false); SoundManager.startBackgroundMusic(); home(); stage.show(); stage.centerOnScreen(); }
    private void scene(Node node) { StackPane root=new StackPane(node); root.getStyleClass().add("app"); Button speaker=b("🔊","volume-button");speaker.setMaxSize(Region.USE_PREF_SIZE,Region.USE_PREF_SIZE);Slider volume=new Slider(0,1,SoundManager.getVolume());volume.setPrefWidth(145);volume.setMaxWidth(145);volume.setAccessibleText("Music volume");volume.valueProperty().addListener((obs,oldValue,newValue)->SoundManager.setVolume(newValue.doubleValue()));VBox audio=new VBox(7,speaker,volume);audio.setAlignment(Pos.TOP_RIGHT);audio.setMaxSize(160,Region.USE_PREF_SIZE);volume.setVisible(false);volume.setManaged(false);audio.setOnMouseEntered(e->{volume.setVisible(true);volume.setManaged(true);});audio.setOnMouseExited(e->{volume.setVisible(false);volume.setManaged(false);});StackPane.setAlignment(audio,Pos.TOP_RIGHT);StackPane.setMargin(audio,new Insets(14,18,0,0));root.getChildren().add(audio); Scene s=new Scene(root,1200,780); s.getStylesheets().add(Objects.requireNonNull(getClass().getResource("styles.css")).toExternalForm()); stage.setScene(s); }
    private Label l(String text,String css){Label x=new Label(text);x.getStyleClass().add(css);return x;} private Button b(String text,String css){Button x=new Button(text);x.getStyleClass().add(css);return x;} private StackPane center(Node n){StackPane p=new StackPane(n);p.setPadding(new Insets(40));return p;}
    private void sound(boolean correct){Toolkit.getDefaultToolkit().beep();if(!correct){PauseTransition repeat=new PauseTransition(Duration.millis(130));repeat.setOnFinished(e->Toolkit.getDefaultToolkit().beep());repeat.play();}}
    private void home(){game.reset();prepareQuestionSets();VBox v=new VBox(18,l("A FIVE-ROUND TRIVIA CHALLENGE","eyebrow"),l("BRAIN\nTEASE","hero"),l("From quick questions to the final lightning round.","subtitle"));v.setAlignment(Pos.CENTER);v.setMaxWidth(720);Button play=b("Start playing","primary");play.setOnAction(e->intro());v.getChildren().addAll(play,l("Best score: "+prefs.getInt("best",0)+" points","muted"));scene(center(v));}
    private void prepareQuestionSets(){List<Q> pool=QuestionBank.uniqueByPrompt(QuestionBank.general());Collections.shuffle(pool);roundOne=new ArrayList<>(pool.subList(0,5));millionaireRound=new ArrayList<>(pool.subList(5,10));lightningRound=new ArrayList<>(pool.subList(10,28));roundTwo=QuestionBank.pick(QuestionBank.trueFalse(),5);jeopardyRound=QuestionBank.jeopardyBoard();}
    private void intro(){VBox v=new VBox(14);v.setMaxWidth(760);v.setAlignment(Pos.CENTER_LEFT);v.getChildren().addAll(l("HOW TO PLAY","eyebrow"),l("Five rounds. One score.","title"),l("Correct answers add points. Wrong answers do not subtract points. Millionaire includes three lifelines. Lightning lasts 45 seconds.","subtitle"),card("01  Multiple Choice","Five mixed-topic questions • 100 points each"),card("02  True or False","Five questions • 150 points each"),card("03  Jeopardy Board","Choose categories and values"),card("04  Millionaire","Five escalating questions with lifelines"),card("05  Lightning Round","45 seconds • 200 points each"));Button go=b("Begin Round 1","primary");go.setOnAction(e->startRoundOne());v.getChildren().add(go);scene(center(v));}
    private void startRoundOne(){game.round=1;game.index=0;standard(roundOne,"ROUND 1 • MULTIPLE CHOICE",100,()->{game.round=2;game.index=0;standard(roundTwo,"ROUND 2 • TRUE OR FALSE",150,this::jeopardy);});}
    private VBox card(String a,String d){VBox v=new VBox(3,l(a,"card-title"),l(d,"muted"));v.getStyleClass().add("card");return v;}
    private HBox head(String title,String sub){HBox h=new HBox();h.setAlignment(Pos.CENTER_LEFT);Region gap=new Region();HBox.setHgrow(gap,Priority.ALWAYS);h.getChildren().addAll(l(title,"round"),gap,l(sub,"muted"));return h;}
    private void standard(List<Q> qs,String title,int value,Runnable done){if(game.index>=qs.size()){done.run();return;}Q q=qs.get(game.index);BorderPane p=new BorderPane();p.setPadding(new Insets(42));p.setTop(head(title,"Question "+(game.index+1)+" of "+qs.size()));VBox box=new VBox(22,l(q.cat.toUpperCase()+" • "+value+" POINTS","eyebrow"));box.getStyleClass().add("question");box.setMaxWidth(880);box.setPrefWidth(880);Label prompt=l(q.text,"question-text");prompt.setWrapText(true);GridPane options=options(q,(i)->{boolean ok=i==q.correct;sound(ok);game.answered++;if(ok){game.correct++;game.score+=value;}game.index++;PauseTransition pause=new PauseTransition(Duration.millis(650));pause.setOnFinished(e->standard(qs,title,value,done));pause.play();});box.getChildren().addAll(prompt,options);p.setCenter(center(box));scene(p);}
    private GridPane options(Q q,java.util.function.IntConsumer action){GridPane g=new GridPane();g.setHgap(14);g.setVgap(14);g.setMaxWidth(Double.MAX_VALUE);g.setPrefWidth(820);ColumnConstraints column=new ColumnConstraints();column.setPercentWidth(50);column.setHgrow(Priority.ALWAYS);g.getColumnConstraints().addAll(column,column);List<Integer> shown=new ArrayList<>();for(int i=0;i<q.a.size();i++){if(game.round==4&&game.fifty&&i!=q.correct&&shown.stream().anyMatch(x->x!=q.correct))continue;shown.add(i);}for(int n=0;n<shown.size();n++){int i=shown.get(n);Button x=b((char)('A'+i)+"  "+q.a.get(i),"answer");x.setMaxWidth(Double.MAX_VALUE);x.setOnAction(e->action.accept(i));g.add(x,n%2,n/2);GridPane.setHgrow(x,Priority.ALWAYS);}return g;}
    private void jeopardy(){game.round=3;BorderPane p=new BorderPane();p.setPadding(new Insets(42));p.setTop(head("ROUND 3 • JEOPARDY BOARD","Choose a category and value"));GridPane board=new GridPane();board.setHgap(14);board.setVgap(14);board.setPrefWidth(1020);board.setMaxWidth(1020);board.setAlignment(Pos.CENTER);for(int c=0;c<3;c++){ColumnConstraints col=new ColumnConstraints();col.setPercentWidth(33.333);col.setHgrow(Priority.ALWAYS);board.getColumnConstraints().add(col);Label h=l(jeopardyRound.get(c*3).cat,"board-head");h.setMaxWidth(Double.MAX_VALUE);board.add(h,c,0);}for(int r=0;r<3;r++)for(int c=0;c<3;c++){Q q=jeopardyRound.get(c*3+r);int value=(r+1)*100;Button x=b(q.used?"✓":"$"+value,"cell");x.setMaxWidth(Double.MAX_VALUE);x.setDisable(q.used);x.setOnAction(e->{q.used=true;jeopardyQuestion(q,value);});board.add(x,c,r+1);GridPane.setHgrow(x,Priority.ALWAYS);}p.setCenter(center(board));scene(p);}
    private void jeopardyQuestion(Q q,int value){BorderPane p=new BorderPane();p.setPadding(new Insets(42));p.setTop(head("ROUND 3 • "+q.cat.toUpperCase(),"$"+value));VBox v=new VBox(20);v.setMaxWidth(840);v.setPrefWidth(840);v.getStyleClass().add("question");Label prompt=l(q.text,"question-text");prompt.setWrapText(true);v.getChildren().add(prompt);for(int i=0;i<4;i++){int k=i;Button x=b((char)('A'+i)+"  "+q.a.get(i),"answer");x.setMaxWidth(Double.MAX_VALUE);x.setOnAction(e->{boolean ok=k==q.correct;sound(ok);game.answered++;if(ok){game.correct++;game.score+=value;}new Alert(Alert.AlertType.INFORMATION,ok?"Correct! You earned $"+value+".":"The answer was: "+q.a.get(q.correct),ButtonType.OK).showAndWait();if(jeopardyRound.stream().allMatch(z->z.used))millionaire();else jeopardy();});v.getChildren().add(x);}p.setCenter(center(v));scene(p);}
    private void millionaire(){game.round=4;game.index=0;millionaireQuestion();}
    private void millionaireQuestion(){if(game.index==millionaireRound.size()){lightning();return;}Q q=millionaireRound.get(game.index);int value=new int[]{500,1000,2000,4000,7500}[game.index];BorderPane p=new BorderPane();p.setPadding(new Insets(42));p.setTop(head("ROUND 4 • MILLIONAIRE","$"+value+" question"));VBox v=new VBox(18);v.setMaxWidth(880);v.getStyleClass().add("question");HBox lifelines=new HBox(10);Button fifty=b("50:50","life"),aud=b("Ask audience","life"),friend=b("Phone a friend","life"),walk=b("Walk away","secondary");fifty.setDisable(game.fifty);aud.setDisable(game.audience);friend.setDisable(game.friend);fifty.setOnAction(e->{game.fifty=true;millionaireQuestion();});aud.setOnAction(e->{game.audience=true;showAudience(q);millionaireQuestion();});friend.setOnAction(e->{game.friend=true;phoneFriend(q);millionaireQuestion();});walk.setOnAction(e->lightning());lifelines.getChildren().addAll(fifty,aud,friend,walk);Label prompt=l(q.text,"question-text");prompt.setWrapText(true);v.getChildren().addAll(lifelines,prompt,options(q,i->{game.answered++;if(i==q.correct){game.correct++;game.score+=value;}game.index++;millionaireQuestion();}));p.setCenter(center(v));scene(p);}
    private void showAudience(Q q){int winner=55+new Random().nextInt(26);int remaining=100-winner;int[] votes=new int[4];votes[q.correct]=winner;List<Integer> wrong=new ArrayList<>();for(int i=0;i<4;i++)if(i!=q.correct)wrong.add(i);for(int index=0;index<wrong.size();index++){int share=index==wrong.size()-1?remaining:new Random().nextInt(remaining+1);votes[wrong.get(index)]=share;remaining-=share;}VBox results=new VBox(10);for(int i=0;i<4;i++){ProgressBar bar=new ProgressBar(votes[i]/100.0);bar.setPrefWidth(280);results.getChildren().add(new HBox(10,l((char)('A'+i)+"  "+q.a.get(i)+"  "+votes[i]+"%","muted"),bar));}Alert alert=new Alert(Alert.AlertType.INFORMATION);alert.setTitle("Ask the Audience");alert.setHeaderText("Audience vote");alert.getDialogPane().setContent(results);alert.showAndWait();}
    private void phoneFriend(Q q){String[] intros={"I am leaning toward", "I would go with", "My best guess is", "I am almost certain it is"};String line="\""+intros[new Random().nextInt(intros.length)]+" "+q.a.get(q.correct)+".\"";SoundManager.speakFriend(line);new Alert(Alert.AlertType.INFORMATION,"Your friend says: "+line,ButtonType.OK).showAndWait();}
    private GridPane millionaireOptions(Q q,java.util.function.IntConsumer action){GridPane g=new GridPane();g.setHgap(14);g.setVgap(14);List<Integer> choices=new ArrayList<>();for(int i=0;i<q.a.size();i++)if(!game.fifty||i==q.correct||choices.stream().noneMatch(x->x!=q.correct))choices.add(i);for(int n=0;n<choices.size();n++){int i=choices.get(n);Button x=b((char)('A'+i)+"  "+q.a.get(i),"answer");x.setMaxWidth(Double.MAX_VALUE);x.setOnAction(e->action.accept(i));g.add(x,n%2,n/2);GridPane.setHgrow(x,Priority.ALWAYS);}return g;}
    private void lightning(){game.round=5;game.index=0;game.seconds=45;lightningDeck=new ArrayList<>(game.lightning);lightningDeck.addAll(List.of(q("Lightning","Which shape has three sides?",1,"Square","Triangle","Circle","Pentagon"),q("Lightning","What is the boiling point of water at sea level?",2,"50°C","90°C","100°C","120°C"),q("Lightning","Which ocean lies between Africa and Australia?",1,"Atlantic","Indian","Pacific","Arctic"),q("Lightning","What do bees collect from flowers?",3,"Sand","Dew","Sap","Nectar"),q("Lightning","Which planet has the most visible rings?",0,"Saturn","Mars","Earth","Neptune"),q("Lightning","What is the largest mammal?",2,"Elephant","Giraffe","Blue whale","Hippopotamus"),q("Lightning","Which color results from mixing blue and yellow?",1,"Purple","Green","Orange","Pink"),q("Lightning","How many days are in a leap year?",3,"364","365","367","366"),q("Lightning","Which metal is liquid at room temperature?",0,"Mercury","Gold","Aluminum","Copper"),q("Lightning","What is the first month of the year?",2,"March","December","January","June"),q("Lightning","Which organ pumps blood through the body?",1,"Lungs","Heart","Brain","Liver"),q("Lightning","What is the currency of Japan?",3,"Won","Yuan","Dollar","Yen")));Collections.shuffle(lightningDeck);BorderPane p=new BorderPane();p.setPadding(new Insets(42));timerLabel=l("45","timer");HBox h=head("FINAL ROUND • LIGHTNING","200 points per correct answer");h.getChildren().add(timerLabel);p.setTop(h);scene(p);askLightning(p);timer=new Timeline(new KeyFrame(Duration.seconds(1),e->{timerLabel.setText(""+--game.seconds);if(game.seconds<=0){timer.stop();results();}}));timer.setCycleCount(Timeline.INDEFINITE);timer.play();}
    private void askLightning(BorderPane p){if(game.index==0){lightningDeck.clear();lightningDeck.addAll(lightningRound);Collections.shuffle(lightningDeck);}if(game.index>=lightningDeck.size()){results();return;}Q q=lightningDeck.get(game.index++);VBox v=new VBox(18,l("CURRENT SCORE: "+game.score,"eyebrow"));v.setMaxWidth(840);v.getStyleClass().add("question");Label prompt=l(q.text,"question-text");prompt.setWrapText(true);v.getChildren().addAll(prompt,options(q,i->{game.answered++;if(i==q.correct){game.correct++;game.score+=200;}askLightning(p);}));p.setCenter(center(v));}
    private void results(){if(timer!=null)timer.stop();SoundManager.playCrowdCheer();int best=Math.max(game.score,prefs.getInt("best",0));prefs.putInt("best",best);int rate=game.answered==0?0:(int)Math.round(game.correct*100.0/game.answered);String msg=rate>=75?"Outstanding work. You are a BrainTease master!":rate>=50?"Great game. You cleared the challenge with a solid score.":"Nice effort. Try again to raise your score.";VBox v=new VBox(18,l("GAME COMPLETE","eyebrow"),l(""+game.score,"score"),l("points","muted"),l(msg,"subtitle"),l(game.correct+" correct from "+game.answered+" answers • "+rate+"% accuracy","stat"),l("Best score: "+best,"muted"));v.setAlignment(Pos.CENTER);v.setMaxWidth(700);v.getStyleClass().add("result");Button replay=b("Play again","primary");replay.setOnAction(e->home());v.getChildren().add(replay);scene(center(v));}
    static class Q{final String cat,text;final List<String>a;final int correct;boolean used;Q(String c,String t,int n,String...x){cat=c;text=t;correct=n;a=List.of(x);}} static Q q(String c,String t,int n,String...x){return new Q(c,t,n,x);}
    private static class Game{int score,correct,answered,index,round,seconds;boolean fifty,audience,friend;final List<Q>mc=List.of(q("Science","What is the chemical symbol for gold?",3,"Ag","Fe","Hg","Au"),q("History","Which year did the first human land on the Moon?",0,"1969","1971","1961","1973"),q("Books","Who wrote Pride and Prejudice?",2,"Emily Brontë","George Eliot","Jane Austen","Virginia Woolf"),q("Geography","What is the largest planet in our solar system?",3,"Earth","Mars","Saturn","Jupiter"),q("Film","Who directed Spirited Away?",1,"Satoshi Kon","Hayao Miyazaki","Makoto Shinkai","Mamoru Hosoda"));final List<Q>tf=List.of(q("True or False","Lightning never strikes the same place twice.",1,"True","False"),q("True or False","An octopus has three hearts.",0,"True","False"),q("True or False","The Great Wall of China is visible from the Moon with the naked eye.",1,"True","False"),q("True or False","A day on Venus is longer than a year on Venus.",0,"True","False"),q("True or False","Sound travels faster in air than in water.",1,"True","False"));final List<Q>j=new ArrayList<>(List.of(q("Science","What force keeps planets in orbit?",2,"Magnetism","Friction","Gravity","Pressure"),q("Science","What gas do plants absorb?",1,"Oxygen","Carbon dioxide","Nitrogen","Helium"),q("Science","What is the hardest natural substance?",3,"Quartz","Iron","Granite","Diamond"),q("Screen & Sound","Which band recorded Bohemian Rhapsody?",0,"Queen","The Beatles","ABBA","U2"),q("Screen & Sound","Which instrument has 88 keys?",1,"Violin","Piano","Trumpet","Flute"),q("Screen & Sound","What is the toy cowboy in Toy Story called?",2,"Buzz","Rex","Woody","Andy"),q("World","What is the capital of Japan?",0,"Tokyo","Seoul","Kyoto","Beijing"),q("World","Which continent contains the Sahara?",2,"Asia","Europe","Africa","South America"),q("World","What is South America's longest river?",1,"Nile","Amazon","Danube","Yangtze")));final List<Q>m=List.of(q("Millionaire","Which animal is called the king of the jungle?",2,"Tiger","Bear","Lion","Wolf"),q("Millionaire","What is Earth's largest ocean?",3,"Atlantic","Indian","Arctic","Pacific"),q("Millionaire","Who developed the theory of relativity?",1,"Isaac Newton","Albert Einstein","Marie Curie","Nikola Tesla"),q("Millionaire","What does CPU stand for?",0,"Central Processing Unit","Computer Personal Unit","Core Program Utility","Central Program User"),q("Millionaire","Which element has atomic number 1?",2,"Helium","Oxygen","Hydrogen","Carbon"));final List<Q>lightning=List.of(q("Lightning","How many continents are there?",1,"5","7","6","8"),q("Lightning","What is the capital of France?",0,"Paris","Rome","Madrid","Berlin"),q("Lightning","Which planet is called the Red Planet?",2,"Venus","Jupiter","Mars","Mercury"),q("Lightning","What is 9 × 8?",3,"63","81","64","72"),q("Lightning","Who painted the Mona Lisa?",1,"Van Gogh","Leonardo da Vinci","Picasso","Monet"),q("Lightning","What is the fastest land animal?",0,"Cheetah","Horse","Lion","Falcon"));void reset(){score=correct=answered=index=round=seconds=0;fifty=audience=friend=false;j.forEach(x->x.used=false);}}
}
